import {useAuth} from '../auth/AuthContext';
import ChangePasswordPage from '../auth/ChangePasswordPage';
import LoginPage from '../components/auth/LoginPage';
import {getAccessToken, getActiveFirmId} from '../api/config';
import TelegramWebApp from './TelegramWebApp';

export default function TelegramBrowserPage() {
  const {user, signOut} = useAuth();
  const token = getAccessToken();
  if (!user || !token) return <LoginPage/>;
  if (user.mustChangePassword) return <ChangePasswordPage/>;
  return <>
    <nav className="tg-browser-nav" aria-label="Навигация приложения">
      <a href={window.location.pathname}>← Полная CRM</a>
      <button onClick={signOut}>Выйти</button>
    </nav>
    <TelegramWebApp crmSession={{token, name: user.name}} initialFirmId={user.role === 'super_admin' ? getActiveFirmId() : ''}/>
  </>;
}
